// frontend/src/components/SearchBar.js
import React, { useState } from 'react';

function SearchBar() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  const handleSearch = async (e) => {
    e.preventDefault();

    try {
      // Use fetch to send a GET request with the query parameter
      const response = await fetch(`http://localhost:4000/api/search?query=${encodeURIComponent(query)}`, {
        method: 'GET',
        credentials: 'include', // Include credentials if your backend uses cookies
      });

      if (!response.ok) {
        throw new Error('Network response was not ok');
      }

      const data = await response.json();
      setResults(data); // Update state with the search results
    } catch (error) {
      console.error('Error fetching search results:', error);
    }
  };

  return (
    <div>

      <div >
      <form onSubmit={handleSearch}
       style={{ width: '100%', display: 'flex', justifyContent: 'center'}}
      >
        <input 

          type="text"
          placeholder="Search locations..."
          style={{ width: '50%', padding: '10px' }}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <button  style={{ padding: '10px' }} type="submit">Search</button>
      </form>
      <ul>
        {results.map((post) => (
          <li key={post.id}>
            <strong>{post.title}</strong>: {post.content}
          </li>
        ))}
      </ul>
      </div>

    </div>
  );
}

export default SearchBar;
